path=r.folder(28)/'own-solves.json'
assert not path.exists()
r.write(path,[dict(id=q['id'],answer=a,reasoning=reason,optionReasons=opts) for q,(a,reason,opts) in zip(r.batch(28),rows)])
r.write(r.folder(28)/'sample.json',{'sample':[{'id':q['id']} for q in r.batch(28)]})
